let nseSeq=0;
function nsFxEl(id){
  const art=NS_FX_ART[id]; if(!art) return null; const n=++nseSeq;
  const w=el("div","nse nse-"+id); w.setAttribute("aria-hidden","true");
  const s=document.createElementNS("http://www.w3.org/2000/svg","svg"); s.setAttribute("viewBox","-10 -24 260 424"); s.setAttribute("preserveAspectRatio","none");
  s.innerHTML=art.replace(/\bid="([^"]+)"/g,`id="$1_${n}"`).replace(/url\(#([^)]+)\)/g,`url(#$1_${n})`).replace(/href="#([^"]+)"/g,`href="#$1_${n}"`);
  w.append(s); return w;
}
/* lay the effect exactly over the profile card (same size, same tilt) */
function nsFxSync(){
  const ov=$("personSheet"), sh=ov?.querySelector(".sheet"), fx=ov?.querySelector(":scope > .nse"); if(!sh||!fx) return;
  Object.assign(fx.style,{left:sh.offsetLeft+"px",top:sh.offsetTop+"px",width:sh.offsetWidth+"px",height:sh.offsetHeight+"px",transform:getComputedStyle(sh).transform});
}
function nsApplyFx(p){
  const ov=$("personSheet"); if(!ov) return;
  const id=nsOf(p).fx, cur=ov.querySelector(":scope > .nse");
  if(cur&&cur.dataset.fx===id){ nsFxSync(); return; }   // same effect: don't restart it on every repaint
  cur?.remove(); if(!id) return;
  const fx=nsFxEl(id); if(!fx) return; fx.dataset.fx=id; ov.append(fx); nsFxSync(); requestAnimationFrame(nsFxSync);
  const once=NS_FX_ONCE[id]; if(once) setTimeout(()=>fx.classList.add("nse-done"),once);   // the big ones play through once, then get out of the way
}
/* effects that cover the card play once per opening; border-style ones keep going */
const NS_FX_ONCE={breach:7600,synthrise:5200};
/* opening a profile (again) always replays the effect from the start */
const _nseOpenPerson=openPerson;
openPerson=function(){ $("personSheet")?.querySelector(":scope > .nse")?.remove(); return _nseOpenPerson.apply(this,arguments); };
const _nseOpenPreview=openProfilePreview;
openProfilePreview=function(){ $("personSheet")?.querySelector(":scope > .nse")?.remove(); return _nseOpenPreview.apply(this,arguments); };
